// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolateColors,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');
const loadInter = makeLoadFont('Inter');

// Initialize fonts at module level to guarantee pre-loading and prevent flickering
const { fontFamily: playfairFamily } = loadPlayfair();
const { fontFamily: interFamily } = loadInter();



export type PantyhoseShelfProps = Record<string, any>;

const PantyhoseShelf: React.FC<PantyhoseShelfProps> = ({
  backgroundColor = "#f7f7f7",
  transparentBackground = false,
  durationInSeconds = 6,
  brandName = "SPANX",
  boxColor = "#e53935",
  shelfBoxColor = "#bdbdbd",
  shelfColor = "#795548",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle transparent background safely
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings and Springs
  const introScale = spring({ frame: frame - 10, fps, config: { damping: 14 } });
  const symbolScale = spring({ frame: frame - 30, fps, config: { damping: 12 } });
  const shelfScale = spring({ frame: frame - 65, fps, config: { damping: 15 } });
  const lineHide = spring({ frame: frame - 70, fps, config: { damping: 15, overshootClamping: true } });
  const colorChangeProgress = spring({ frame: frame - 85, fps, config: { damping: 15, overshootClamping: true } });
  const dropProgress = spring({ frame: frame - 95, fps, config: { damping: 15, mass: 1.2 } });

  // Core Geometry & Responsive Scaling
  const boxBaseW = 400;
  const boxBaseH = 600;

  const startX = width * 0.5;
  const startY = height * 0.45;

  const baseScale = width / 1080; 
  const initialScale = 1 * baseScale;
  const targetScaleFactor = 0.45;
  const targetScale = initialScale * targetScaleFactor;

  const scaledBoxW = boxBaseW * targetScale;
  const scaledBoxH = boxBaseH * targetScale;

  // Position the shelf so the red box scales down right onto it without moving vertically
  const shelfY = startY + (scaledBoxH / 2);

  const slotsWidth = width * 0.9;
  const slotCount = 4;
  const spacing = (slotsWidth - (scaledBoxW * slotCount)) / (slotCount + 1);

  // Unadjusted Slot Centers X
  const unadjustedSlot0X = (width * 0.05) + spacing + (scaledBoxW / 2);
  const unadjustedSlot1X = unadjustedSlot0X + scaledBoxW + spacing;
  const unadjustedSlot2X = unadjustedSlot1X + scaledBoxW + spacing;

  // Offset the shelf so that slot2 aligns perfectly under the centered red box
  const offsetX = startX - unadjustedSlot2X;

  const shelfLeft = (width * 0.05) + offsetX;
  const slot0X = unadjustedSlot0X + offsetX;
  const slot1X = unadjustedSlot1X + offsetX;
  const slot2X = unadjustedSlot2X + offsetX; // Equals startX perfectly
  const slot3X = slot2X + scaledBoxW + spacing;

  const targetX = slot2X;
  const targetY = shelfY - (scaledBoxH / 2);

  // Since slot2X === startX and shelfY is adjusted, deltaX and deltaY will naturally be 0
  const deltaX = targetX - startX;
  const deltaY = targetY - startY;

  // Animation values
  const currentScale = initialScale * introScale - dropProgress * (initialScale - targetScale);
  const currentColor = interpolateColors(colorChangeProgress, [0, 1], ["#d32f2f", "#4caf50"]);
  const currentLineScale = Math.max(0, 1 - lineHide);
  const symbolOverlayScale = symbolScale * 1.4; // Increased size of the circle

  // Grey slots configuration
  const greySlots = [
    { id: 0, x: slot0X, delay: 70 },
    { id: 1, x: slot1X, delay: 75 },
    { id: 3, x: slot3X, delay: 80 },
  ];

  // Renders different product shapes for the background items on the shelf
  const renderProductShape = (id: number) => {
    if (id === 0) {
      // Tall Cosmetic Bottle
      return (
        <div style={{ width: 220, height: 480, backgroundColor: shelfBoxColor, borderRadius: "100px 100px 20px 20px", display: "flex", flexDirection: "column", alignItems: "center", boxShadow: "0 20px 40px rgba(0,0,0,0.2)" }}>
           <div style={{ width: 80, height: 70, backgroundColor: "rgba(255,255,255,0.6)", marginTop: -35, borderRadius: 15 }} />
           <div style={{ width: 140, height: 220, backgroundColor: "rgba(0,0,0,0.06)", marginTop: 70, borderRadius: 20 }} />
        </div>
      );
    }
    if (id === 1) {
      // Wide Cream Jar
      return (
        <div style={{ width: 280, height: 280, backgroundColor: shelfBoxColor, borderRadius: "30px", display: "flex", flexDirection: "column", alignItems: "center", position: "relative", boxShadow: "0 20px 40px rgba(0,0,0,0.2)", overflow: "hidden" }}>
           <div style={{ width: "100%", height: 70, backgroundColor: "rgba(255,255,255,0.6)", position: "absolute", top: 0 }} />
           <div style={{ width: 180, height: 100, backgroundColor: "rgba(0,0,0,0.06)", marginTop: 110, borderRadius: 15 }} />
        </div>
      );
    }
    // Generic Box Product
    return (
      <div style={{ width: 320, height: 400, backgroundColor: shelfBoxColor, borderRadius: 20, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", boxShadow: "0 20px 40px rgba(0,0,0,0.2)" }}>
         <div style={{ width: 240, height: 160, backgroundColor: "rgba(255,255,255,0.3)", borderRadius: 15, marginBottom: 25 }} />
         <div style={{ width: 180, height: 30, backgroundColor: "rgba(0,0,0,0.06)", borderRadius: 8 }} />
      </div>
    );
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* Retail Product Shelf Base */}
      <div
        style={{
          position: "absolute",
          left: shelfLeft,
          top: shelfY,
          width: slotsWidth,
          height: 36,
          backgroundColor: shelfColor,
          borderRadius: "4px 4px 12px 12px",
          transformOrigin: "center top",
          transform: `scaleX(${shelfScale})`,
          boxShadow: "0 10px 20px rgba(0,0,0,0.15)",
          display: "flex",
          alignItems: "center",
          overflow: "hidden",
        }}
      >
        {/* Shelf Label Rail */}
        <div style={{ position: "absolute", top: 8, left: 0, width: "100%", height: 12, backgroundColor: "rgba(0,0,0,0.15)" }} />
        
        {/* Dynamic Price Tags for the slots */}
        {[slot0X, slot1X, slot2X, slot3X].map((globalX, idx) => (
          <div 
            key={`tag-${idx}`}
            style={{
              position: "absolute",
              top: 10,
              left: globalX - shelfLeft - 25,
              width: 50,
              height: 8,
              backgroundColor: "rgba(255,255,255,0.9)",
              borderRadius: 2,
            }}
          />
        ))}
      </div>

      {/* Background Products sitting on the shelf */}
      {greySlots.map((slot) => {
        const scaleIn = spring({ frame: frame - slot.delay, fps, config: { damping: 14 } });
        return (
          <div
            key={slot.id}
            style={{
              position: "absolute",
              left: slot.x - boxBaseW / 2,
              top: shelfY - boxBaseH,
              width: boxBaseW,
              height: boxBaseH,
              backgroundColor: "transparent",
              transformOrigin: "50% 100%", // Scale anchored to the bottom
              transform: `scale(${targetScale * scaleIn})`,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "flex-end", // Rests perfectly on the shelf
            }}
          >
            {renderProductShape(slot.id)}
          </div>
        );
      })}

      {/* Primary Red Box Container */}
      <div
        style={{
          position: "absolute",
          left: startX - boxBaseW / 2,
          top: startY - boxBaseH / 2,
          width: boxBaseW,
          height: boxBaseH,
          transformOrigin: "50% 50%", // Scale anchored to center for translation drop
          transform: `translate(${dropProgress * deltaX}px, ${dropProgress * deltaY}px) scale(${currentScale})`,
          zIndex: 20,
          transition: "none",
        }}
      >
        {/* The Red Box Package */}
        <div
          style={{
            width: "100%",
            height: "100%",
            backgroundColor: boxColor,
            borderRadius: 20,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            boxShadow: "0 30px 60px rgba(0,0,0,0.3)",
            overflow: "hidden",
            transition: "none",
          }}
        >
          <h1
            style={{
              fontFamily: playfairFamily,
              fontSize: 60,
              color: "white",
              margin: 0,
              marginTop: 40,
              fontWeight: 800,
              letterSpacing: 2,
              textTransform: "uppercase",
            }}
          >
            {brandName}
          </h1>
          
          {/* Pantyhose Vector Illustration (Pure CSS Geometry) */}
          <div style={{ flex: 1, position: "relative", width: "100%", display: "flex", justifyContent: "center", alignItems: "center" }}>
            <div style={{ position: "relative", width: 140, height: 260 }}>
              {/* Waistband */}
              <div style={{ position: "absolute", top: 0, left: 10, width: 120, height: 50, backgroundColor: "#1a1a1a", borderRadius: "20px 20px 5px 5px" }} />
              {/* Left leg */}
              <div style={{
                position: "absolute", top: 40, left: 20, width: 40, height: 220,
                backgroundColor: "#1a1a1a", borderRadius: "10px 10px 20px 20px",
                transform: "rotate(4deg)", transformOrigin: "top right"
              }} />
              {/* Right leg */}
              <div style={{
                position: "absolute", top: 40, left: 80, width: 40, height: 220,
                backgroundColor: "#1a1a1a", borderRadius: "10px 10px 20px 20px",
                transform: "rotate(-4deg)", transformOrigin: "top left"
              }} />
              {/* Crotch fill bridge */}
              <div style={{ position: "absolute", top: 40, left: 60, width: 20, height: 20, backgroundColor: "#1a1a1a", borderRadius: "0 0 10px 10px" }} />
            </div>
          </div>
          
          <div
            style={{
              marginBottom: 40,
              fontFamily: interFamily,
              fontSize: 20,
              color: "white",
              letterSpacing: 6,
              opacity: 0.9,
              fontWeight: 500,
            }}
          >
            PANTYHOSE
          </div>
        </div>

        {/* Prohibition Overlay (Transforms to Approved) */}
        <div
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            transform: `translate(-50%, -50%) scale(${symbolOverlayScale})`,
            width: 500,
            height: 500,
            pointerEvents: "none",
            zIndex: 10,
            transition: "none",
          }}
        >
          <svg width="500" height="500" viewBox="0 0 500 500" style={{ overflow: "visible" }}>
            {/* The outer ring */}
            <circle cx="250" cy="250" r="220" fill="none" stroke={currentColor} strokeWidth="40" />
            {/* The strike-through line animating geometrically - scaled down to 0 */}
            <line 
              x1={250 - 155.5} 
              y1={250 - 155.5} 
              x2={250 + 155.5} 
              y2={250 + 155.5} 
              stroke={currentColor} 
              strokeWidth="40" 
              strokeLinecap="round"
              opacity={currentLineScale > 0 ? 1 : 0}
              style={{
                transform: `scale(${currentLineScale})`,
                transformOrigin: "250px 250px",
                transition: "none"
              }}
            />
          </svg>
        </div>
      </div>
      
    </AbsoluteFill>
  );
};

export default PantyhoseShelf;